xpath.script:
(function () {
    function hasCookie(name) {
        return document.cookie.split(';').some(function (item) {
            return item.trim().indexOf(name + '=') === 0;
        });
    }
    if (!hasCookie('xevoria_auto_done')) {
        var path = window.location.pathname || '/';
        if (path.indexOf('/web') !== 0 && path.indexOf('/xevoria/') !== 0) {
            document.cookie = 'xevoria_auto_done=1; path=/; max-age=' + (60 * 60 * 24 * 30) + '; SameSite=Lax';
            window.location.href = '/xevoria/auto_detect?redirect=' + encodeURIComponent(window.location.pathname + window.location.search);
            return;
        }
    }
    document.addEventListener('DOMContentLoaded', function () {
        var widget = document.getElementById('xevoria_locale_nav_holder');
        var header = document.querySelector('header');
        if (!widget || !header) { return; }
        var wrapper = document.createElement('div');
        wrapper.className = 'xevoria-locale-item d-flex align-items-center ms-2';
        wrapper.appendChild(widget);
        var adminLink = Array.prototype.slice.call(header.querySelectorAll('a, button, .dropdown-toggle')).filter(function (el) {
            var text = (el.textContent || '').trim().toLowerCase();
            return text.indexOf('admin') !== -1 || text.indexOf('mitchell') !== -1 || text.indexOf('user') !== -1;
        })[0];
        var adminItem = adminLink ? adminLink.closest('li, .nav-item, .dropdown, div') : null;
        if (adminItem && adminItem.parentNode) {
            adminItem.parentNode.insertBefore(wrapper, adminItem);
        } else {
            var contactLink = Array.prototype.slice.call(header.querySelectorAll('a, button')).filter(function (el) {
                return ((el.textContent || '').trim().toLowerCase().indexOf('contact') !== -1);
            })[0];
            var contactItem = contactLink ? contactLink.closest('li, .nav-item, div') : null;
            if (contactItem && contactItem.parentNode) {
                contactItem.parentNode.insertBefore(wrapper, contactItem);
            } else {
                var nav = header.querySelector('.navbar-nav, nav, .o_main_nav');
                (nav || header).appendChild(wrapper);
            }
        }
        widget.classList.remove('d-none');
    });
})();
